      .modal-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      @media (max-width: 640px) {
        .preview-media,
        .preview-content {
          padding: 20px;
        }

        .actions,
        .modal-actions {
          flex-direction: column;
          align-items: stretch;
        }
      }
    </style>
  </head>
  <body>
    <div id="app"></div>
    <script>
      const state = {
        isDialogOpen: false,
        imageDeleted: false
      };

      const image = {
        title: "Aurora Coastline",
        description: "A moody long-exposure shot with layered clouds and soft neon reflections across the water.",
        src: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80",
        size: "12.4 MB",
        resolution: "6000 x 4000"
      };

      function ImageMetaPill(label, value) {
        return `<span class="meta-pill">${label}: ${value}</span>`;
      }

      function PreviewCard() {
        const details = state.imageDeleted
          ? {
              title: "Image removed",
              description: "This image has been deleted from your library.",
              src: "https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&w=1200&q=80"
            }
          : image;

        return `
          <main class="app-shell">
            <section class="preview-card" aria-labelledby="preview-title">
              <div class="preview-media">
                <img src="${details.src}" alt="${details.title}" />
              </div>
              <div class="preview-content">
                <p class="eyebrow">Library Preview</p>
                <h1 id="preview-title">${details.title}</h1>
                <p class="description">${details.description}</p>
                <div class="meta-row">
                  ${ImageMetaPill("Resolution", image.resolution)}
                  ${ImageMetaPill("Size", image.size)}
                </div>
                <div class="actions">
                  <p class="supporting-text">Delete this image if you no longer want it in your library.</p>
                  <button type="button" class="trigger" ${state.imageDeleted ? "disabled" : ""}>Delete image</button>
                </div>
              </div>
            </section>
          </main>
        `;
      }

      function DeleteDialog() {
        return `
          <div class="modal-root" ${state.isDialogOpen ? "" : "hidden"}>
            <div class="modal-backdrop" data-close-dialog="true"></div>
            <section
              class="modal-panel"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
            >
              <div class="modal-badge" aria-hidden="true">!</div>
              <h2 id="dialog-title">Delete this image?</h2>
              <p id="dialog-description">
                This will permanently remove the image from your library. You can’t undo this action once it’s confirmed.
              </p>
              <div class="modal-actions">
                <button type="button" class="ghost-button" data-close-dialog="true">Cancel</button>
                <button type="button" class="danger-button" data-confirm-delete="true">Delete</button>
              </div>
            </section>
          </div>
        `;
      }

      function App() {
        return `
          ${PreviewCard()}
          ${DeleteDialog()}
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();

        const trigger = document.querySelector(".trigger");
        if (trigger) {
          trigger.addEventListener("click", openDialog);
        }

        document.querySelectorAll("[data-close-dialog='true']").forEach((element) => {
          element.addEventListener("click", closeDialog);
        });

        const confirmButton = document.querySelector("[data-confirm-delete='true']");
        if (confirmButton) {
          confirmButton.addEventListener("click", confirmDelete);
        }
      }

      function openDialog() {
        state.isDialogOpen = true;
        render();
      }

      function closeDialog() {
        state.isDialogOpen = false;
        render();
      }

      function confirmDelete() {
        state.isDialogOpen = false;
        state.imageDeleted = true;
        render();
      }

      render();
    </script>
  </body>
</html>
